import React, { useState } from 'react';
import Aura from '../components/Aura';
import { analyzeThought } from '../hooks/useGroq';
import { useThoughts } from '../hooks/useStorage';

const GOLD = '#C8A96E';

const s = {
  label: { fontFamily: 'DM Mono, monospace', fontSize: 9, letterSpacing: '0.22em', textTransform: 'uppercase', color: 'rgba(237,233,224,0.3)' },
};

export default function Home({ setPage, streak }) {
  const [text,      setText]      = useState('');
  const [loading,   setLoading]   = useState(false);
  const [error,     setError]     = useState('');
  const [result,    setResult]    = useState(null);
  const [inputOpen, setInputOpen] = useState(false);
  const { addThought } = useThoughts();

  const submit = async () => {
    if (!text.trim() || loading) return;
    setLoading(true); setError('');
    try {
      const ai = await analyzeThought(text);
      const entry = { id: Date.now(), user_text: text, ...ai, date: new Date().toISOString() };
      addThought(entry);
      setResult(entry);
      setInputOpen(false);
    } catch { setError('Försök igen.'); }
    setLoading(false);
  };

  if (result) return <Analysis result={result} text={text} onBack={() => { setResult(null); setText(''); }} setPage={setPage} />;

  return (
    <div style={{ position: 'relative', height: '100vh', overflow: 'hidden', background: '#080808' }}>
      <Aura colors={['#1A2A5E', '#2A1A6E']} intensity={0.7} />

      <div style={{ position: 'absolute', top: 32, left: 24, zIndex: 10 }}>
        <span style={{ ...s.label, color: 'rgba(237,233,224,0.28)', letterSpacing: '0.2em' }}>Spiral</span>
      </div>

      {streak > 0 && (
        <div style={{ position: 'absolute', top: 30, right: 24, zIndex: 10 }}>
          <span style={{ fontFamily: 'DM Mono, monospace', fontSize: 9, color: 'rgba(237,233,224,0.3)', letterSpacing: '0.08em' }}>
            🔥 {streak}
          </span>
        </div>
      )}

      {!inputOpen && (
        <div style={{ position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', zIndex: 10, animation: 'fadeIn .8s ease both', textAlign: 'center', padding: '0 28px' }}>
          <p style={{ ...s.label, marginBottom: 20, color: 'rgba(237,233,224,0.22)', letterSpacing: '0.3em' }}>Tankeanalys</p>
          <h1 style={{ fontSize: 'clamp(42px,11vw,72px)', fontWeight: 800, letterSpacing: '-0.05em', lineHeight: 1.02, color: '#ede9e0', marginBottom: 14 }}>
            Vad tänker<br />du på?
          </h1>
          <p style={{ fontSize: 14, fontWeight: 400, color: 'rgba(237,233,224,0.38)', lineHeight: 1.75, maxWidth: 260, marginBottom: 52 }}>
            Skriv ner vad som snurrar. AI:n identifierar tankefällan och hjälper dig se klarare.
          </p>
          <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
            <button
              onClick={() => setInputOpen(true)}
              style={{ padding: '14px 28px', borderRadius: 100, background: '#ede9e0', color: '#080808', fontSize: 14, fontWeight: 700, letterSpacing: '-0.01em', display: 'inline-flex', alignItems: 'center', gap: 8, transition: 'all 0.2s' }}
              onMouseEnter={e => e.currentTarget.style.background = '#fff'}
              onMouseLeave={e => e.currentTarget.style.background = '#ede9e0'}
            >
              Skriv en tanke <span style={{ opacity: 0.4 }}>↗</span>
            </button>
            <button
              onClick={() => setPage('checkin')}
              style={{ width: 52, height: 52, borderRadius: '50%', background: 'rgba(255,255,255,0.07)', border: '0.5px solid rgba(255,255,255,0.12)', color: 'rgba(237,233,224,0.6)', fontSize: 18, display: 'flex', alignItems: 'center', justifyContent: 'center', transition: 'all 0.2s' }}
              onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,255,255,0.12)'}
              onMouseLeave={e => e.currentTarget.style.background = 'rgba(255,255,255,0.07)'}
            >
              ◎
            </button>
          </div>
        </div>
      )}

      {inputOpen && (
        <div style={{ position: 'absolute', inset: 0, zIndex: 20, display: 'flex', flexDirection: 'column', justifyContent: 'flex-end', animation: 'fadeUp .4s cubic-bezier(0.16,1,0.3,1) both' }}>
          <div onClick={() => setInputOpen(false)} style={{ position: 'absolute', inset: 0 }} />
          <div style={{ position: 'relative', margin: '0 12px 28px' }}>
            <div style={{ background: 'rgba(14,14,14,0.9)', backdropFilter: 'blur(32px)', borderRadius: 24, border: '0.5px solid rgba(255,255,255,0.12)', overflow: 'hidden' }}>
              <div style={{ padding: '20px 20px 0' }}>
                <p style={{ ...s.label, marginBottom: 14, color: 'rgba(237,233,224,0.28)' }}>Vad tänker du på?</p>
                <textarea
                  autoFocus
                  value={text}
                  onChange={e => setText(e.target.value)}
                  maxLength={1000}
                  placeholder="Skriv fritt — inga rätta svar..."
                  style={{ width: '100%', minHeight: 120, background: 'transparent', border: 'none', color: '#ede9e0', fontSize: 16, fontWeight: 400, lineHeight: 1.75, resize: 'none', outline: 'none', letterSpacing: '-0.01em' }}
                />
              </div>
              <div style={{ padding: '12px 20px 20px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderTop: '0.5px solid rgba(255,255,255,0.07)' }}>
                <span style={{ ...s.label, color: 'rgba(237,233,224,0.18)' }}>{text.length}/1000</span>
                <button
                  onClick={submit}
                  disabled={!text.trim() || loading}
                  style={{ padding: '11px 26px', borderRadius: 100, background: text.trim() && !loading ? GOLD : 'rgba(255,255,255,0.07)', color: text.trim() && !loading ? '#080808' : 'rgba(237,233,224,0.2)', fontSize: 13, fontWeight: 700, border: 'none', transition: 'all .2s', letterSpacing: '-0.01em' }}
                >
                  {loading
                    ? <span style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                        <span style={{ width: 10, height: 10, border: '2px solid rgba(0,0,0,0.2)', borderTopColor: '#080808', borderRadius: '50%', display: 'inline-block', animation: 'spin .7s linear infinite' }} />
                        Analyserar
                      </span>
                    : 'Analysera →'}
                </button>
              </div>
              {error && <p style={{ padding: '0 20px 16px', fontSize: 12, color: 'rgba(220,100,100,0.8)' }}>{error}</p>}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

