    <div style={{ position: 'relative', height: '100vh', overflow: 'hidden', background: '#080808' }}>
      <Aura colors={['#4A1020', '#6E1A10']} intensity={0.6} />
      <div style={{ position: 'absolute', inset: 0, zIndex: 10, display: 'flex', flexDirection: 'column', padding: '36px 22px', overflowY: 'auto', paddingBottom: 110 }}>

        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 36 }}>
