        </div>

        <div style={{ textAlign: 'center', marginBottom: 36 }}>
          <div style={{ fontSize: 52, marginBottom: 14 }}>{result.trap_icon}</div>
          <p style={{ ...s.label, marginBottom: 10 }}>Tankefälla</p>
          <h2 style={{ fontSize: 'clamp(28px,8vw,42px)', fontWeight: 800, letterSpacing: '-0.04em', color: '#ede9e0', lineHeight: 1.08 }}>{result.trap_label}</h2>
        </div>

        <div style={{ background: 'rgba(200,169,110,0.05)', borderLeft: `2px solid ${GOLD}`, borderRadius: '0 20px 20px 0', padding: '14px 18px', marginBottom: 12 }}>
          <p style={{ fontSize: 13, color: 'rgba(237,233,224,0.42)', fontStyle: 'italic', lineHeight: 1.75 }}>"{text.slice(0, 120)}{text.length > 120 ? '...' : ''}"</p>
        </div>

        {[
          { label: 'Vad händer', body: result.description },
          { label: 'Omramning',  body: result.reframe },
          { label: 'Övning',     body: result.exercise_text },
        ].map(({ label, body }) => (
          <div key={label} style={{ background: 'rgba(255,255,255,0.04)', border: '0.5px solid rgba(255,255,255,0.08)', borderRadius: 22, padding: '18px', marginBottom: 10 }}>
            <p style={{ ...s.label, marginBottom: 10, color: 'rgba(200,169,110,0.7)' }}>{label}</p>
            <p style={{ fontSize: 14, color: 'rgba(237,233,224,0.78)', lineHeight: 1.85, fontWeight: 400 }}>{body}</p>
          </div>
        ))}

        <button
          onClick={() => setPage('breathing')}
          style={{ padding: '14px', borderRadius: 100, background: 'rgba(255,255,255,0.07)', border: '0.5px solid rgba(255,255,255,0.12)', color: 'rgba(237,233,224,0.6)', fontSize: 14, marginTop: 4, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8 }}
        >
          🫁 Andningsövning
        </button>
      </div>
    </div>
  );
}
